package com.adaptivelearning.execution.domain;import com.adaptivelearning.shared.exception.BusinessException;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.*;
class TaskStatusPolicyTest {@Test void completedCanOnlyBeReversedToPaused(){assertThatCode(()->TaskStatusPolicy.require("COMPLETED","PAUSED")).doesNotThrowAnyException();assertThatThrownBy(()->TaskStatusPolicy.require("COMPLETED","IN_PROGRESS")).isInstanceOf(BusinessException.class);}@Test void canceledIsTerminal(){assertThatThrownBy(()->TaskStatusPolicy.require("CANCELED","IN_PROGRESS")).isInstanceOf(BusinessException.class);}}
